Your expense tracker is below: add an item, pick a category, set a monthly budget and watch the totals update. Figures stay only while the page is open, so note down the total before you close it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f7f7f5;color:#222}
  h2{margin:0 0 12px;font-size:18px}
  .card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0002}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
  input,select,button{font-size:14px;padding:8px;border:1px solid #ccc;border-radius:6px}
  input{flex:1;min-width:90px}
  button{background:#2f7d5b;color:#fff;border:none;cursor:pointer}
  button.x{background:none;color:#b33;padding:2px 8px}
  .bar{height:10px;background:#e5e5e0;border-radius:5px;overflow:hidden}
  .fill{height:100%;background:#2f7d5b;width:0}
  .over{background:#c0392b}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
  .small{font-size:12px;color:#666}
  .cat{margin:6px 0}
  .cat .bar{height:6px}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="row">
    <label class="small" style="align-self:center">Budget (₹)</label>
    <input id="budget" type="number" value="30000" min="0">
  </div>
  <div class="bar"><div id="fill" class="fill"></div></div>
  <div id="summary" class="small" style="margin-top:6px"></div>
</div>

<div class="card">
  <div class="row">
    <input id="name" type="text" placeholder="What was it?">
    <input id="amt" type="number" placeholder="Amount (₹)" min="0">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <button type="button" id="add">Add expense</button>
  </div>
</div>

<div class="card">
  <strong>By category</strong>
  <div id="cats"></div>
</div>

<div class="card">
  <strong>All expenses</strong>
  <div id="list" class="small">Nothing added yet.</div>
</div>

<script>
var items=[];
function inr(n){return "₹"+Number(n).toLocaleString("en-IN",{maximumFractionDigits:0});}
function render(){
  var total=0,by={};
  items.forEach(function(i){total+=i.amt;by[i.cat]=(by[i.cat]||0)+i.amt;});
  var b=Number(document.getElementById("budget").value)||0;
  var pct=b>0?Math.min(100,total/b*100):0;
  var f=document.getElementById("fill");
  f.style.width=pct+"%";
  f.className="fill"+(b>0&&total>b?" over":"");
  var left=b-total;
  document.getElementById("summary").textContent="Spent "+inr(total)+" of "+inr(b)+" · "+(left>=0?inr(left)+" left":inr(-left)+" over budget");
  var c=document.getElementById("cats");
  c.innerHTML="";
  Object.keys(by).sort(function(a,z){return by[z]-by[a];}).forEach(function(k){
    var d=document.createElement("div");d.className="cat";
    var p=total>0?by[k]/total*100:0;
    d.innerHTML="<div class='item' style='border:none;padding:0'><span>"+k+"</span><span>"+inr(by[k])+"</span></div><div class='bar'><div class='fill' style='width:"+p+"%'></div></div>";
    c.appendChild(d);
  });
  if(!items.length)c.innerHTML="<div class='small'>No data yet.</div>";
  var l=document.getElementById("list");
  l.innerHTML="";
  if(!items.length){l.textContent="Nothing added yet.";return;}
  items.forEach(function(i,idx){
    var d=document.createElement("div");d.className="item";
    var s=document.createElement("span");
    s.textContent=i.name+" · "+i.cat;
    var r=document.createElement("span");
    r.textContent=inr(i.amt)+" ";
    var x=document.createElement("button");
    x.type="button";x.className="x";x.textContent="✕";
    x.onclick=function(){items.splice(idx,1);render();};
    r.appendChild(x);
    d.appendChild(s);d.appendChild(r);
    l.appendChild(d);
  });
}
document.getElementById("add").onclick=function(){
  var n=document.getElementById("name").value.trim();
  var a=Number(document.getElementById("amt").value);
  if(!n||!(a>0))return;
  items.unshift({name:n,amt:a,cat:document.getElementById("cat").value});
  document.getElementById("name").value="";
  document.getElementById("amt").value="";
  render();
};
document.getElementById("budget").oninput=render;
render();
</script>
</body>
</html>
```
